      } catch (reason) {
        results.push({
          scenario,
          iteration,
          repetitionCount,
          status: 'failed',
          error: reason instanceof Error ? reason.message : String(reason),
        })
      }
      if (interruptionSignal?.aborted) return results
    }
  }
  return results
}

export function smokeScenarioEnvironment(
